UPDATE "partner_programs" SET "long_description" = 'A Outlier AI conecta especialistas a tarefas de treinamento e avaliação de modelos de inteligência artificial. O trabalho pode envolver análise de respostas, escrita, raciocínio, programação ou comparação de resultados. A aprovação, a disponibilidade de projetos, o valor por hora e a continuidade variam conforme país, idioma, experiência e demanda. Antes de iniciar, leia o briefing, confirme os critérios de qualidade e considere que o volume de tarefas pode oscilar.'
WHERE "slug" = 'outlier-ai';
